CREATE TABLE IF NOT EXISTS gis_provider_connectors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, provider_name text NOT NULL, authority_name text, provider_type text NOT NULL, base_url text NOT NULL, auth_mode text NOT NULL DEFAULT 'none', status text NOT NULL DEFAULT 'Configured', trust_level text NOT NULL DEFAULT 'Reference', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_provider_datasets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), connector_id uuid NOT NULL REFERENCES gis_provider_connectors(id) ON DELETE CASCADE, dataset_name text NOT NULL, endpoint_url text NOT NULL, format text NOT NULL, boundary_level text NOT NULL, expected_feature_count integer, source_dataset_version text, status text NOT NULL DEFAULT 'Configured', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_provider_retrievals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES gis_provider_datasets(id) ON DELETE CASCADE, requested_at timestamptz NOT NULL DEFAULT now(), http_status integer, content_type text, content_length bigint, payload_hash text, retrieval_status text NOT NULL DEFAULT 'Pending', error_code text, error_message text, imported_dataset_id uuid REFERENCES gis_boundary_datasets(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_provider_connectors_jurisdiction ON gis_provider_connectors(jurisdiction_id,status);
CREATE INDEX IF NOT EXISTS idx_gis_provider_datasets_connector ON gis_provider_datasets(connector_id,status);
CREATE INDEX IF NOT EXISTS idx_gis_provider_retrievals_dataset ON gis_provider_retrievals(dataset_id,requested_at DESC);